def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]

    segments = []
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            if abs(r2 - r1) == abs(c2 - c1) and r2 != r1:
                dr = 1 if r2 > r1 else -1
                dc = 1 if c2 > c1 else -1
                segments.append((r1, c1, r2, c2, dr, dc))
                r, c = r1, c1
                while True:
                    if out[r][c] == bg:
                        out[r][c] = 1
                    if (r, c) == (r2, c2):
                        break
                    r += dr
                    c += dc

    for r, c in sixes:
        for r1, c1, r2, c2, dr, dc in segments:
            if (r - r1) * dc == (c - c1) * dr and \
               min(r1, r2) <= r <= max(r1, r2) and \
               min(c1, c2) <= c <= max(c1, c2):
                # Extend perpendicular to the 1-line.
                step_c = -dr * dc
                for k in range(-max(h, w), max(h, w) + 1):
                    rr = r + k
                    cc = c + k * step_c
                    if 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                        out[rr][cc] = 6
                break

    return out
